-- Disposable local database only, after the existing Melon migrations and Studio 001.
begin;
create function pg_temp.check_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',message; end if;end$$;
create function pg_temp.expect_error(statement text,expected text default null) returns void language plpgsql as $$begin begin execute statement;exception when others then if expected is null or sqlstate=expected then return;end if;raise;end;raise exception 'FAIL: allowed %',statement;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values
 ('91000000-0000-4000-8000-000000000001','studio-admin@columbia.edu',now(),'{"provider":"google"}'),
 ('91000000-0000-4000-8000-000000000002','studio-member@columbia.edu',now(),'{"provider":"google"}');
insert into auth.identities(user_id,provider) values('91000000-0000-4000-8000-000000000001','google'),('91000000-0000-4000-8000-000000000002','google');
insert into public.profiles(id,email,is_superadmin) select id,email,id='91000000-0000-4000-8000-000000000001' from auth.users;
set local role anon;
select pg_temp.expect_error($q$select public.studio_list_chains()$q$,'42501');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","app_metadata":{"provider":"google"},"amr":[{"method":"oauth"}]}',true);
select pg_temp.expect_error($q$select public.studio_list_chains()$q$,'42501');
select pg_temp.expect_error($q$select public.studio_save_chain(null,null,'Injected','',false)$q$,'42501');
select pg_temp.expect_error($q$select public.studio_get_run(gen_random_uuid())$q$,'42501');
select pg_temp.expect_error($q$select * from public.prompt_studio_runs$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name) values('prompt-studio-assets','91000000-0000-4000-8000-000000000002/no.png')$q$,'42501');
select pg_temp.expect_error($q$select public.studio_assign_order(gen_random_uuid(),array[]::uuid[])$q$,'42501');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","app_metadata":{"provider":"google"},"amr":[{"method":"password"}]}',true);
select pg_temp.expect_error($q$select public.studio_models()$q$,'42501');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","app_metadata":{"provider":"google"},"amr":[{"method":"oauth"}]}',true);
do $$declare chain uuid;other_chain uuid;step1 uuid;step2 uuid;step3 uuid;plan jsonb;request uuid;revision integer;record jsonb;begin
 chain:=public.studio_save_chain(null,null,'SQL Studio test','A real editable workflow.',true);
 perform pg_temp.check_true(jsonb_array_length(public.studio_get_chain(chain)->'steps')=3,'starter has three steps');
 perform pg_temp.check_true(public.studio_get_chain(chain)->>'in_melon_mix'='false','new chain excluded from Melon mix');
 step1:=(public.studio_get_chain(chain)->'steps'->0->>'id')::uuid;
 step2:=(public.studio_get_chain(chain)->'steps'->1->>'id')::uuid;
 step3:=(public.studio_get_chain(chain)->'steps'->2->>'id')::uuid;
 perform public.studio_reorder_steps(chain,0,array[step2,step1,step3]);
 perform pg_temp.check_true(public.studio_get_chain(chain)->'steps'->0->>'id'=step2::text,'reorder step 2 to step 1');
 perform pg_temp.expect_error(format('select public.studio_reorder_steps(%L,0,array[%L,%L,%L]::uuid[])',chain,step1,step2,step3));
 perform pg_temp.expect_error(format('select public.studio_reorder_steps(%L,1,array[%L,%L,%L]::uuid[])',chain,step1,step1,step3));
 other_chain:=public.studio_save_chain(null,null,'Other chain','',true);
 perform pg_temp.expect_error(format('select public.studio_delete_step(%L,0,%L)',other_chain,step1));
 perform public.studio_save_chain(chain,1,'Updated chain','Edited description',false);
 perform pg_temp.check_true(public.studio_get_chain(chain)->>'name'='Updated chain','chain update');
 perform public.studio_save_step(chain,2,step1,jsonb_build_object('name','Edited image observer','system_prompt','Only visible facts.','user_prompt','Direction: {{prompt}}','llm_model_id','d6200000-0000-4000-8000-000000000001','temperature',0.4,'studio_input_type','image_and_text','studio_output_type','text','studio_max_tokens',512));
 perform pg_temp.expect_error(format('select public.studio_begin_run(%L,3,%L,null)',chain,'A caption direction'));
 insert into storage.objects(bucket_id,name) values('prompt-studio-assets',auth.uid()::text||'/test.png');
 plan:=public.studio_begin_run(chain,3,'A test caption direction',auth.uid()::text||'/test.png');request:=(plan->>'request_id')::uuid;
 perform pg_temp.check_true(plan->'steps'->0->>'input_type'='text','snapshot preserves text input');
 perform pg_temp.expect_error(format('select public.studio_save_chain(%L,3,%L,%L,false)',chain,'Do not edit during run',''));
 perform pg_temp.expect_error(format('select public.studio_complete_run(%L)',request));
 perform pg_temp.expect_error(format('select public.studio_record_response(%L,%L,%L,1,1,1,%L)',request,step3,'Wrong step.','Wrong'));
 perform public.studio_record_response(request,step2,'A funny angle.',10,5,100,'Actual prompt 1.');
 perform public.studio_record_response(request,step1,'Students on campus.',20,6,200,'Actual prompt 2.');
 perform public.studio_record_response(request,step3,'["Caption one.","Caption two."]',30,7,300,'Actual prompt 3.');
 perform public.studio_complete_run(request);perform public.studio_complete_run(request);
 record:=public.studio_get_run(request);
 perform pg_temp.check_true(record->>'status'='completed','complete and idempotent');
 perform pg_temp.check_true(record->>'final_output'='["Caption one.","Caption two."]','final output saved');
 perform pg_temp.check_true(jsonb_array_length(record->'responses')=3,'responses visible');
 perform pg_temp.check_true(record->>'image_bucket'='prompt-studio-assets','private source image');
 perform pg_temp.check_true((public.studio_list_runs(chain)->>'total')::int=1,'chain-specific media');
 perform public.studio_delete_step(chain,3,step1);
 perform pg_temp.check_true(jsonb_array_length(public.studio_get_chain(chain)->'steps')=2,'delete step');
 perform pg_temp.check_true(public.studio_get_chain(chain)->'steps'->1->>'step_order'='2','delete closes ordering gaps');
 perform public.studio_delete_chain(chain,4);
 perform pg_temp.check_true(public.studio_get_chain(chain) is null,'delete chain');
 record:=public.studio_get_run(request);
 perform pg_temp.check_true(record->>'chain_name'='Updated chain','deleted chain name preserved');
 perform pg_temp.check_true(record->>'final_output'='["Caption one.","Caption two."]','deleting definitions preserves output');
 perform pg_temp.check_true(jsonb_array_length(record->'responses')=3,'deleting definitions preserves responses');
 perform pg_temp.check_true(record->'responses'->0->'snapshot' is not null,'response snapshots survive deletion');
 perform pg_temp.check_true(public.studio_image_in_use(auth.uid()::text||'/test.png'),'referenced image retained');
 delete from storage.objects where bucket_id='prompt-studio-assets' and name=auth.uid()::text||'/test.png';
 perform pg_temp.check_true(exists(select 1 from storage.objects where bucket_id='prompt-studio-assets' and name=auth.uid()::text||'/test.png'),'cannot delete referenced source image');
 perform public.studio_delete_chain(other_chain,0);
end$$;
reset role;
update public.profiles set is_superadmin=false where id='91000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select public.studio_list_runs()$q$,'42501');
select pg_temp.check_true((select count(*)=0 from storage.objects where bucket_id='prompt-studio-assets'),'revoked admin cannot view studio assets');
rollback;
